'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { Receipt, Mail, Lock, ArrowRight, CheckCircle } from 'lucide-react';
import { Button, Input, Card } from '@/components/ui/base';
import { signIn } from "next-auth/react";

export default function LoginPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    // Simulate login delay
    setTimeout(() => {
      setLoading(false);
      router.push('/dashboard');
    }, 1500);
  };

  return (
    <div className="min-h-screen flex text-gray-900 bg-gray-50">
      {/* Visual Side */}
      <div className="hidden lg:flex flex-col justify-between w-1/2 bg-[#111827] text-white p-12 relative overflow-hidden">
        {/* Background Elements */}
        <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 rounded-full bg-green-500 opacity-10 blur-3xl"></div>
        <div className="absolute bottom-0 left-0 -ml-20 -mb-20 w-80 h-80 rounded-full bg-blue-500 opacity-10 blur-3xl"></div>
        
        <div className="relative z-10">
          <div className="flex items-center gap-2 mb-12">
            <div className="bg-green-500 p-2 rounded">
              <Receipt className="h-6 w-6 text-white" />
            </div>
            <span className="text-2xl font-bold tracking-tight">Finora</span>
          </div>
          
          <h1 className="text-4xl font-bold leading-tight mb-6">
            Master your money with <br/>
            <span className="text-green-400">AI-powered insights.</span>
          </h1>
          
          <p className="text-gray-400 text-lg max-w-md">
            Finora helps you track expenses, budget smarter, and reach your financial goals with advanced predictive analytics.
          </p>
        </div>

        <div className="grid grid-cols-2 gap-4 relative z-10 mt-12 bg-white/5 p-6 rounded-2xl border border-white/10 backdrop-blur-sm">
          <div className="flex items-start gap-3">
            <CheckCircle className="text-green-400 mt-1 shrink-0" size={20} />
            <div>
              <h3 className="font-semibold text-white">Smart OCR</h3>
              <p className="text-sm text-gray-400 mt-1">Scan receipts instantly</p>
            </div>
          </div>
          <div className="flex items-start gap-3">
             <CheckCircle className="text-green-400 mt-1 shrink-0" size={20} />
            <div>
              <h3 className="font-semibold text-white">Forecasting</h3>
              <p className="text-sm text-gray-400 mt-1">Predict future spending</p>
            </div>
          </div>
          <div className="flex items-start gap-3">
             <CheckCircle className="text-green-400 mt-1 shrink-0" size={20} />
            <div>
              <h3 className="font-semibold text-white">Voice Log</h3>
              <p className="text-sm text-gray-400 mt-1">Record on the go</p>
            </div>
          </div>
          <div className="flex items-start gap-3">
             <CheckCircle className="text-green-400 mt-1 shrink-0" size={20} />
            <div>
              <h3 className="font-semibold text-white">Secure</h3>
              <p className="text-sm text-gray-400 mt-1">Bank-grade encryption</p>
            </div>
          </div>
        </div>

        <div className="text-sm text-gray-500 relative z-10">
          © 2026 Finora Inc. All rights reserved.
        </div>
      </div>

      {/* Login Side */}
      <div className="flex-1 flex flex-col justify-center items-center p-8 lg:p-12 relative">
        <div className="w-full max-w-md space-y-8">
          <div className="text-center lg:text-left">
            <h2 className="text-3xl font-bold text-gray-900">Sign in</h2>
            <p className="mt-2 text-gray-500">
              New to Finora?{' '}
              <Link href="/register" className="text-green-600 font-medium hover:text-green-500">
                Create an account
              </Link>
            </p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Email address</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Mail className="h-5 w-5 text-gray-400" />
                </div>
                <Input type="email" placeholder="you@example.com" className="pl-10 h-12" required />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Password</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Lock className="h-5 w-5 text-gray-400" />
                </div>
                <Input type="password" placeholder="••••••••" className="pl-10 h-12" required />
              </div>
              <div className="flex justify-end mt-2">
                <Link href="#" className="text-sm text-green-600 hover:text-green-500">
                  Forgot password?
                </Link>
              </div>
            </div>

            <Button 
              disabled={loading}
              className={`w-full h-12 text-base bg-green-600 hover:bg-green-700 flex justify-center items-center gap-2 ${loading ? 'opacity-70 cursor-not-allowed' : ''}`}
            >
              {loading ? (
                <>Loading...</>
              ) : (
                <>Sign In <ArrowRight size={18} /></>
              )}
            </Button>
          </form>

          <div className="relative">
            <div className="absolute inset-0 flex items-center">
              <div className="w-full border-t border-gray-300"></div>
            </div>
            <div className="relative flex justify-center text-sm">
              <span className="px-2 bg-gray-50 text-gray-500">Or continue with</span>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <button 
              type="button"
              onClick={() => signIn('google', { callbackUrl: '/dashboard' })}
              className="flex items-center justify-center py-3 border border-gray-300 rounded-lg hover:bg-gray-100 transition-colors"
            >
              <svg className="h-5 w-5 mr-2" viewBox="0 0 24 24">
                 <path
                  d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                  fill="#4285F4"
                />
                <path
                  d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                  fill="#34A853"
                />
                <path
                  d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.26.81-.58z"
                  fill="#FBBC05"
                />
                <path
                  d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                  fill="#EA4335"
                />
              </svg>
              Google
            </button>
            <button className="flex items-center justify-center py-3 border border-gray-300 rounded-lg hover:bg-gray-100 transition-colors">
              <span className="font-bold text-gray-900 mr-2">G</span>
              GitHub
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
